// Same verdict for both callers: known "already exists" answers are fine, the end state is what counts.
function checkSetup(res, errs) {
  const err = (k) => errs[k] ? `${errs[k].error ?? ''} ${errs[k].error_description ?? ''}`.trim() : null;
  const problems = [];
  if (!res.info) problems.push(`app.info: ${err('info') ?? 'no result'}`);
  if (res.profile && !res.profile.ADMIN) problems.push('the user is not a portal administrator');
  const ignorable = (k) => !errs[k] || /already|ALREADY/i.test(err(k));
  for (const k of ['ev_deal', 'ev_uninstall', 'robot_add']) if (!ignorable(k)) problems.push(`${k}: ${err(k)}`);
  for (const k of ['robot_update', 'tab_bind']) if (errs[k]) problems.push(`${k}: ${err(k)}`);
  const bound = (res.events ?? []).map((e) => `${e.event}->${e.handler}`);
  for (const ev of ['ONCRMDEALUPDATE', 'ONAPPUNINSTALL']) if (!bound.some((x) => x.startsWith(ev))) problems.push(`event ${ev} not bound`);
  if (res.robots && !res.robots.includes(ROBOT.CODE)) problems.push(`robot ${ROBOT.CODE} not registered`);
  if (res.placements && !res.placements.some((x) => x.placement === 'CRM_DEAL_DETAIL_TAB')) problems.push('placement CRM_DEAL_DETAIL_TAB not bound');
  const report = {
    app: res.info ? { id: res.info.ID, code: res.info.CODE, version: res.info.VERSION, installed: res.info.INSTALLED } : null,
    installer: res.profile ? { id: res.profile.ID, admin: res.profile.ADMIN } : null,
    events: bound, robots: res.robots ?? [], placements: (res.placements ?? []).map((x) => x.placement),
    ignored: Object.fromEntries(['ev_deal', 'ev_uninstall', 'robot_add', 'tab_unbind'].filter((k) => errs[k]).map((k) => [k, err(k)])),
    at: new Date().toISOString(),
  };
  return { ok: problems.length === 0, problems, report };
}

