// Bitrix24 opens the install path with POST: AUTH_ID, AUTH_EXPIRES, REFRESH_ID, APPLICATION_TOKEN,
// member_id, SERVER_ENDPOINT, status (body) and DOMAIN, PROTOCOL, LANG, APP_SID (query).
const b = $json.body ?? {}, q = $json.query ?? {};
const v = (k) => b[k] ?? q[k] ?? null;
return [{ json: { auth_id: v('AUTH_ID'), refresh_id: v('REFRESH_ID'), expires: Number(v('AUTH_EXPIRES') ?? 3600),
                  application_token: v('APPLICATION_TOKEN'), member_id: v('member_id'), domain: String(v('DOMAIN') ?? '').toLowerCase(),
                  server_endpoint: v('SERVER_ENDPOINT'), scope: v('APPLICATION_SCOPE') } }];

// Form-encoded event: flat keys like auth[application_token]. ONAPPINSTALL / ONAPPUPDATE carry a NEW
// application_token (Bitrix24 re-keys the app after installFinish), so they cannot be checked against the
// stored one: they are authenticated by their own access_token (docs: "safe event handlers").
const b = $json.body ?? {};
const a = (k) => b.auth?.[k] ?? b[`auth[${k}]`] ?? null;
const event = String(b.event ?? '').toUpperCase();
return [{ json: { event, rekey: ['ONAPPINSTALL', 'ONAPPUPDATE'].includes(event),
  application_token: a('application_token'), access_token: a('access_token'), refresh_token: a('refresh_token'),
  expires_in: Number(a('expires_in') ?? 3600), member_id: a('member_id'), domain: String(a('domain') ?? '').toLowerCase(),
  client_endpoint: a('client_endpoint') } }];

